            .is_some_and(|(was, was_name)| *was != ix || *was_name != name);
        if changed && ix + 1 != self.tasks.len() && self.selected_task.is_none() {
            self.scroll_output_to_top();
        }
        self.latest_settled = Some((ix, name));
    }''')
# push_task selects the new task
