            this.tasks[code].status = TaskStatus::Done;
            this.settle_latest();
            cx.notify();
        });
        assert_eq!(state(cx), (Some(code), vec![code]));
        let next = push(cx);
        assert_eq!(state(cx), (Some(next), vec![next]));
    }
''')
open(p,'w').write(s)
